  const CUSTO_POR_CIRCULO = { 1: 1, 2: 3, 3: 6, 4: 10 };
  const CIRCULO_ROMANO = { 1: "I", 2: "II", 3: "III", 4: "IV" };

  function forma(raw) {
    if (!raw) return null;
    return { pe: raw[0], circulo: raw[1], afinidade: Boolean(raw[2]), texto: raw[3] };
  }

  const lista = ROWS.map((row) => ({
    id: row[0],
    nome: row[1],
    elementos: row[2],
    circulo: row[3],
    custo: CUSTO_POR_CIRCULO[row[3]],
    execucao: row[4],
    alcance: row[5],
    alvo: row[6],
    duracao: row[7],
    resistencia: row[8],
    descricao: row[9],
    discente: forma(row[10]),
    verdadeiro: forma(row[11]),
    fonte: row[12],
    // Amaldiçoar Arma: o elemento é escolhido ao aprender o ritual.
    escolheElemento: row[0] === "amaldicoar-arma",
  })).sort((a, b) => a.circulo - b.circulo || a.nome.localeCompare(b.nome, "pt-BR"));

  const porId = new Map(lista.map((ritual) => [ritual.id, ritual]));

  window.RITUAIS = {
    lista,
    porId,
    get: (id) => porId.get(id) || null,
    CUSTO_POR_CIRCULO,
    CIRCULO_ROMANO,
    ELEMENTOS: [C, E, M, S, D],
    FONTES: [LB, SH, AS],
  };
